preConditionHook:
// THE MICRO TREND LINE. Same machinery as TrendLineTouch -- the two most recent
// CONFIRMED swing pivots, the bull line across the LOWS and the bear line
// across the HIGHS, TLValue's FIRST-anchor two-point projection -- but read at
// microSwingStrength 1 and with the ADDITIONAL requirement that the two anchors
// lie no more than microLineBars apart. That span test is what makes this a
// MICRO line and not the swing line.
//
// The pivot scan is INLINED rather than reaching into SwingHigh.json -- rules
// in this corpus never reference each other -- and mirrors the EL twin's
// SwingLow / SwingLowBar / SwingHigh / SwingHighBar at Occurrence 1 and 2.
//
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min): the pivot
// test is MIXED -- AT OR ABOVE the microSwingStrength OLDER bars, STRICTLY
// ABOVE the microSwingStrength NEWER bars -- so a flat top yields exactly one
// pivot, the later of the equal bars; bars-ago indexing makes the SMALLER index
// the NEWER bar, so the strict half is the k < j loop. The confirmation lag is
// exactly microSwingStrength bars -- ONE bar here, the minimum that is still
// lookahead-safe. pivotLookback is EL's Length (offsets 0..pivotLookback-1
// inclusive) and the neighbourhood test reaches microSwingStrength bars PAST
// the window, so the deepest index the scan touches is
// pivotLookback - 1 + microSwingStrength. A window with no pivot returns the -1
// SENTINEL, guarded below. Occurrence 3+ is UNMEASURED and never asked for. The
// comparisons carry the 2.22e-12 relational tolerance, hence el_gt / el_ge.
// Strength 1 is inside the measured range; Length below Strength+1 is not, and
// pivotLookback 20 is far above it. No WFSafe_SwingHigh exists, so plain EL
// governs.
//
// MEASURED, EL_TLValue_Probe.txt: the two-point line anchored at the FIRST
// pair, Slope = (P2 - P1) / (B2 - B1); value = P1 + (target - B1) * Slope,
// extrapolating freely, so it can be read at the poking bar. Bars-ago
// convention, OLDER pivot as P1/B1 (the zero-drift spelling). Bar1 = Bar2
// silently returns 0.0 and is guarded rather than relied on. The slope is
// hoisted out of the per-target arithmetic where the EL twin recomputes it
// inside each TLValue call; identical doubles, same line.
//
// THIS RULE: the FAILED micro-breakout, back in the micro-trend's direction. A
// bar within the last failureWindowBars poked THROUGH the micro line -- for a
// LONG, a bar whose low traded below the bull micro line -- and the market has
// now closed back through that bar's own opposite extreme (close above that
// bar's high). Brooks's span is '2 to about 10 bars'; R00-39 read 6 and T16-08
// read 10, default 10.
//
// Deliberately NOT merged with TrendLineTouch: a poke that FAILS within a bar
// or two and a closing price beyond the line are opposite trades. Also distinct from
// MicroChannelFailedBreakoutEntry, which breaks a micro CHANNEL -- a run of
// bars none of which made a lower low -- rather than a projected line: price
// can poke through this line without breaking any bar-to-bar structure, and a
// micro channel can end without any line being touched.
//
// The scan runs NEWEST FIRST and keeps the first hit, so the poking bar is the
// most recent one and its extreme is the level the close must clear.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivS = (int)microSwingStrength;
pivW = (int)pivotLookback;
loP1 = -1.0;
loB1 = -1.0;
loP2 = -1.0;
loB2 = -1.0;
foundLo = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundLo;
        if (foundLo == 1) { loP2 = low[j]; loB2 = (double)j; }
        else { loP1 = low[j]; loB1 = (double)j; break; }
    }
}
hiP1 = -1.0;
hiB1 = -1.0;
hiP2 = -1.0;
hiB2 = -1.0;
foundHi = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundHi;
        if (foundHi == 1) { hiP2 = high[j]; hiB2 = (double)j; }
        else { hiP1 = high[j]; hiB1 = (double)j; break; }
    }
}
haveLoLine = (foundLo == 2) && (loB1 != loB2) && el_le(loB1 - loB2, microLineBars);
haveHiLine = (foundHi == 2) && (hiB1 != hiB2) && el_le(hiB1 - hiB2, microLineBars);
loSlope = 0.0;
hiSlope = 0.0;
if (haveLoLine) loSlope = (loP2 - loP1) / (loB2 - loB1);
if (haveHiLine) hiSlope = (hiP2 - hiP1) / (hiB2 - hiB1);
pokeLoFound = false;
pokeHiFound = false;
pokeLoHigh = 0.0;
pokeHiLow = 0.0;
for (int kk = 1; kk <= (int)failureWindowBars; ++kk) {
    if (haveLoLine && !pokeLoFound && el_lt(low[kk], loP1 + ((double)kk - loB1) * loSlope)) {
        pokeLoFound = true;
        pokeLoHigh = high[kk];
    }
    if (haveHiLine && !pokeHiFound && el_gt(high[kk], hiP1 + ((double)kk - hiB1) * hiSlope)) {
        pokeHiFound = true;
        pokeHiLow = low[kk];
    }
}
